sp_widget.client_script:
api.controller = function($scope, $timeout) {

    var c = this;


    /* =========================================================
       INITIAL STATE
       ========================================================= */

    c.loading = false;

    c.saving = false;

    c.showModal = false;

    c.selectedInterview = null;


    c.form = {

        interviewer: '',

        round_name: '',

        interview_date: '',

        status: ''
    };


    /* =========================================================
       LOAD PAGE
       ========================================================= */

    c.loadPage = function(page) {

        if (
            !page ||
            page < 1
        ) {

            page = 1;
        }


        c.loading = true;


        c.server.get({

            page:
                page,

            search:
                c.data.search || '',

            statusFilter:
                c.data.statusFilter || ''

        }).then(

            function(response) {

                if (
                    response &&
                    response.data
                ) {

                    c.data =
                        response.data;
                }


                c.loading = false;
            },

            function() {

                c.loading = false;
            }
        );
    };


    /* =========================================================
       SEARCH
       ========================================================= */

    c.searchInterviews = function() {

        c.data.page = 1;

        c.loadPage(1);
    };


    /* =========================================================
       FILTER STATUS
       ========================================================= */

    c.filterStatus = function() {

        c.data.page = 1;

        c.loadPage(1);
    };


    /* =========================================================
       CLEAR FILTERS
       ========================================================= */

    c.clearFilters = function() {

        c.data.search = '';

        c.data.statusFilter = '';

        c.data.page = 1;

        c.loadPage(1);
    };


    /* =========================================================
       NEXT PAGE
       ========================================================= */

    c.nextPage = function() {

        if (
            c.data.hasNext
        ) {

            var nextPage =
                parseInt(
                    c.data.page,
                    10
                ) + 1;


            c.loadPage(
                nextPage
            );
        }
    };


    /* =========================================================
       PREVIOUS PAGE
       ========================================================= */

    c.previousPage = function() {

        if (
            c.data.hasPrevious
        ) {

            var previousPage =
                parseInt(
                    c.data.page,
                    10
                ) - 1;


            c.loadPage(
                previousPage
            );
        }
    };


    /* =========================================================
       REFRESH
       ========================================================= */

    c.refresh = function() {

        c.loadPage(
            c.data.page || 1
        );
    };


    /* =========================================================
       OPEN EDIT MODAL
       ========================================================= */

    c.openEdit = function(
        interview
    ) {

        if (
            !c.data.canEdit
        ) {

            return;
        }


        if (!interview) {

            return;
        }


        c.selectedInterview =
            interview;


        c.form = {

            interviewer:
                interview.interviewerId ||
                '',

            round_name:
                (
                    interview.round &&
                    interview.round !== 'Not Set'
                )
                    ? interview.round
                    : '',

            interview_date:
                c.toDateTimeLocal(
                    interview.interviewDate
                ),

            status:
                interview.statusValue ||
                ''
        };


        c.showModal = true;
    };


    /* =========================================================
       CLOSE MODAL
       ========================================================= */

    c.closeModal = function() {

        c.showModal = false;

        c.selectedInterview = null;


        c.form = {

            interviewer: '',

            round_name: '',

            interview_date: '',

            status: ''
        };
    };


    /* =========================================================
       DATE CONVERSION
       ========================================================= */

    c.toDateTimeLocal = function(
        value
    ) {

        if (!value) {

            return '';
        }


        value =
            (
                value + ''
            ).replace(
                ' ',
                'T'
            );


        /*
         * datetime-local requires:
         *
         * YYYY-MM-DDTHH:mm
         */

        if (
            value.length >= 16
        ) {

            return value.substring(
                0,
                16
            );
        }


        return value;
    };


    /* =========================================================
       SAVE SCHEDULE
       ========================================================= */

    c.saveSchedule = function() {

        if (
            !c.selectedInterview ||
            c.saving
        ) {

            return;
        }


        c.saving = true;


        c.server.get({

            action:
                'saveSchedule',

            interviewId:
                c.selectedInterview.sys_id,

            interviewer:
                c.form.interviewer,

            round_name:
                c.form.round_name,

            interview_date:
                c.form.interview_date,

            status:
                c.form.status

        }).then(

            function(response) {

                c.saving = false;


                if (
                    response &&
                    response.data &&
                    response.data.saveResult
                ) {

                    c.closeModal();


                    /*
                     * Reload same page.
                     *
                     * This refreshes:
                     * - Interview list
                     * - Status
                     * - Interviewer
                     * - Date
                     * - Summary counts
                     */

                    c.loadPage(
                        c.data.page || 1
                    );

                } else {

                    alert(

                        (
                            response &&
                            response.data &&
                            response.data.saveMessage
                        ) ||

                        'Unable to update interview.'
                    );
                }
            },

            function() {

                c.saving = false;


                alert(
                    'Unable to update interview.'
                );
            }
        );
    };


    /* =========================================================
       ESCAPE / CLEANUP
       ========================================================= */

    $scope.$on(
        '$destroy',
        function() {

            c.showModal = false;

            c.selectedInterview = null;
        }
    );

};

sp_widget.css:
/* =========================================================
   NEXORA INTERVIEW MANAGEMENT
   ========================================================= */

.nexora-main {
    width: 85vw;
    min-height: 100vh;
    padding: 70px;
    background: #ffffff;
    color: #172b3f;
    font-family: "Inter", "Segoe UI", Arial, sans-serif;
    box-sizing: border-box;
}


/* =========================================================
   PAGE HEADER - NEXORA HERO STYLE
   ========================================================= */

.nx-page-header {
    position: relative;
    width: 100%;
    min-height: 205px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 34px;
    margin-bottom: 28px;
    overflow: hidden;
    box-sizing: border-box;

    border-radius: 22px;

    background:
        linear-gradient(
            135deg,
            #17334b 0%,
            #1b3b55 55%,
            #244963 100%
        );

    box-shadow:
        0 16px 40px rgba(23, 51, 75, 0.16);

    color: #ffffff;
}


/* =========================================================
   HEADER DECORATIVE CIRCLES
   ========================================================= */

.nx-page-header::before {
    content: "";
    position: absolute;
    width: 260px;
    height: 260px;
    right: -80px;
    top: -125px;

    border-radius: 50%;

    background: rgba(255, 107, 91, 0.13);

    pointer-events: none;
}


.nx-page-header::after {
    content: "";
    position: absolute;
    width: 210px;
    height: 210px;
    right: 80px;
    bottom: -145px;

    border-radius: 50%;

    border: 1px solid rgba(255, 255, 255, 0.10);

    pointer-events: none;
}


/* =========================================================
   HEADER CONTENT
   ========================================================= */

.nx-header-content {
    position: relative;
    z-index: 2;

    flex: 1;

    display: flex;
    align-items: center;

    min-width: 0;
}


.nx-header-text {
    max-width: 760px;
}


/* =========================================================
   EYEBROW
   ========================================================= */

.nx-eyebrow {
    font-size: 11px;
    font-weight: 800;
    letter-spacing: 1.8px;
    text-transform: uppercase;

    color: #ff7465;

    margin-bottom: 8px;
}


/* =========================================================
   HEADER TITLE
   ========================================================= */

.nx-page-header h1 {
    margin: 0;

    color: #ffffff;

    font-size: 38px;
    line-height: 1.08;

    font-weight: 800;

    letter-spacing: -1px;
}


/* =========================================================
   HEADER DESCRIPTION
   ========================================================= */

.nx-header-description {
    max-width: 690px;

    margin: 12px 0 0;

    color: rgba(255, 255, 255, 0.68);

    font-size: 13px;
    line-height: 1.65;
}


/* =========================================================
   HEADER STAT
   ========================================================= */
/* =========================================================
   HERO REFRESH BUTTON
   ========================================================= */

/* =========================================================
   HERO REFRESH BUTTON — NEXORA CORAL THEME
   ========================================================= */

.nx-hero-refresh-btn {
    position: relative;
    z-index: 2;

    height: 44px;
    padding: 0 19px;

    display: flex;
    align-items: center;
    justify-content: center;
    gap: 9px;

    margin-left: 35px;

    border: 1px solid #ff6b5b;
    border-radius: 11px;

    background: #ff6b5b;

    color: #ffffff;

    font-size: 12px;
    font-weight: 700;

    cursor: pointer;

    box-shadow: 0 8px 20px rgba(255, 107, 91, 0.25);

    transition:
        background 0.2s ease,
        border-color 0.2s ease,
        transform 0.2s ease,
        box-shadow 0.2s ease;
}

.nx-hero-refresh-btn:hover:not(:disabled) {
    background: #ff5948;
    border-color: #ff5948;

    transform: translateY(-2px);

    box-shadow: 0 10px 24px rgba(255, 107, 91, 0.35);
}

.nx-hero-refresh-btn:active:not(:disabled) {
    transform: translateY(0);
}

.nx-hero-refresh-btn i {
    font-size: 13px;
}

.nx-hero-refresh-btn:disabled {
    opacity: 0.65;
    cursor: not-allowed;
    transform: none;
}

/* =========================================================
   REFRESH
   =========================================================
   Kept unchanged in case refresh button is used elsewhere.
   ========================================================= */

.nx-refresh-btn {
    border: 0;
    outline: none;
    padding: 12px 19px;
    border-radius: 10px;
    background: #17334b;
    color: #ffffff;
    font-size: 13px;
    font-weight: 650;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 8px;
    box-shadow: 0 5px 15px rgba(23, 51, 75, 0.14);
    transition: all 0.2s ease;
}

.nx-refresh-btn:hover {
    background: #20435d;
    transform: translateY(-1px);
}

.nx-refresh-btn:disabled {
    opacity: 0.65;
    cursor: not-allowed;
}


/* =========================================================
   SUMMARY GRID
   ========================================================= */

.nx-summary-grid {
    width: 100%;
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 18px;
    margin-bottom: 25px;
}

.nx-summary-card {
    background: #ffffff;
    border: 1px solid #e7ebf0;
    border-radius: 15px;
    padding: 20px;
    display: flex;
    align-items: center;
    gap: 15px;
    min-height: 112px;
    box-shadow: 0 5px 20px rgba(24, 43, 63, 0.045);
    transition: all 0.2s ease;
}

.nx-summary-card:hover {
    transform: translateY(-2px);
    box-shadow: 0 9px 25px rgba(24, 43, 63, 0.08);
}

.nx-summary-icon {
    width: 47px;
    height: 47px;
    min-width: 47px;
    border-radius: 12px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 19px;
}

.nx-blue {
    background: #e9f1f8;
    color: #17334b;
}

.nx-coral {
    background: #fff0ed;
    color: #ff6b5b;
}

.nx-purple {
    background: #f0edfa;
    color: #7159a8;
}

.nx-green {
    background: #e9f7ef;
    color: #2d9b65;
}

.nx-summary-content {
    min-width: 0;
}

.nx-summary-label {
    font-size: 10px;
    font-weight: 750;
    letter-spacing: 1px;
    color: #8190a3;
    margin-bottom: 3px;
}

.nx-summary-value {
    font-size: 27px;
    line-height: 1.1;
    font-weight: 750;
    color: #17334b;
}

.nx-summary-sub {
    font-size: 11px;
    color: #9aa5b4;
    margin-top: 4px;
}


/* =========================================================
   MAIN CARD
   ========================================================= */

.nx-interview-card {
    background: #ffffff;
    border: 1px solid #e5e9ef;
    border-radius: 17px;
    overflow: hidden;
    box-shadow: 0 6px 25px rgba(24, 43, 63, 0.055);
}


/* =========================================================
   CARD HEADER
   ========================================================= */

.nx-interview-header {
    padding: 22px 25px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    border-bottom: 1px solid #edf0f4;
}

.nx-interview-title {
    display: flex;
    align-items: center;
    gap: 13px;
}

.nx-section-icon {
    width: 42px;
    height: 42px;
    border-radius: 11px;
    background: #17334b;
    color: #ffffff;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 17px;
}

.nx-interview-title h2 {
    margin: 0;
    color: #17334b;
    font-size: 18px;
    font-weight: 750;
}

.nx-interview-title p {
    margin: 4px 0 0;
    color: #8a96a7;
    font-size: 12px;
}

.nx-record-count {
    background: #f3f5f8;
    color: #66768a;
    border-radius: 20px;
    padding: 7px 13px;
    font-size: 11px;
    font-weight: 700;
}


/* =========================================================
   FILTER BAR
   ========================================================= */

.nx-filter-bar {
    padding: 18px 25px;
    background: #fafbfc;
    border-bottom: 1px solid #edf0f4;
    display: flex;
    align-items: center;
    gap: 12px;
}

.nx-search-box {
    flex: 1;
    min-width: 250px;
    position: relative;
}

.nx-search-box i {
    position: absolute;
    left: 14px;
    top: 50%;
    transform: translateY(-50%);
    color: #9aa6b5;
    font-size: 13px;
}

.nx-search-box input {
    width: 100%;
    height: 41px;
    border: 1px solid #dfe4ea;
    border-radius: 9px;
    padding: 0 14px 0 38px;
    outline: none;
    background: #ffffff;
    color: #26394c;
    font-size: 12px;
    box-sizing: border-box;
    transition: border-color 0.2s ease;
}

.nx-search-box input:focus {
    border-color: #ff6b5b;
    box-shadow: 0 0 0 3px rgba(255, 107, 91, 0.08);
}

.nx-search-box input::placeholder {
    color: #a6afbb;
}

.nx-filter-select {
    height: 41px;
    min-width: 160px;
    border: 1px solid #dfe4ea;
    border-radius: 9px;
    padding: 0 12px;
    outline: none;
    background: #ffffff;
    color: #43566b;
    font-size: 12px;
    cursor: pointer;
}

.nx-filter-select:focus {
    border-color: #ff6b5b;
}

.nx-clear-btn {
    height: 41px;
    padding: 0 17px;
    border-radius: 9px;
    border: 1px solid #dfe4ea;
    background: #ffffff;
    color: #647489;
    font-size: 12px;
    font-weight: 650;
    cursor: pointer;
}

.nx-clear-btn:hover {
    border-color: #ff6b5b;
    color: #ff6b5b;
}


/* =========================================================
   LOADING
   ========================================================= */

.nx-loading {
    min-height: 220px;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    color: #7d8b9c;
    font-size: 13px;
}

.nx-loading i {
    color: #ff6b5b;
}


/* =========================================================
   EMPTY STATE
   ========================================================= */

.nx-empty-state {
    min-height: 290px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 35px;
    text-align: center;
}

.nx-empty-icon {
    width: 58px;
    height: 58px;
    border-radius: 50%;
    background: #f1f4f7;
    color: #9ba7b6;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 22px;
    margin-bottom: 15px;
}

.nx-empty-state h3 {
    margin: 0;
    font-size: 17px;
    color: #34495e;
}

.nx-empty-state p {
    margin: 7px 0 0;
    color: #8a96a7;
    font-size: 12px;
}


/* =========================================================
   INTERVIEW LIST
   ========================================================= */

.nx-interview-list {
    width: 100%;
}

.nx-interview-row {
    display: grid;
    grid-template-columns:
        minmax(185px, 1.35fr)
        minmax(130px, 1fr)
        minmax(135px, 1fr)
        minmax(105px, 0.8fr)
        minmax(145px, 1fr)
        minmax(105px, 0.8fr)
        48px;

    align-items: center;
    gap: 12px;
    padding: 17px 25px;
    border-bottom: 1px solid #eef1f4;
    min-height: 78px;
    box-sizing: border-box;
    transition: background 0.18s ease;
}

.nx-interview-row:hover {
    background: #fbfcfd;
}

.nx-student-column {
    display: flex;
    align-items: center;
    gap: 11px;
    min-width: 0;
}

.nx-student-avatar {
    width: 37px;
    height: 37px;
    min-width: 37px;
    border-radius: 10px;
    background: #17334b;
    color: #ffffff;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 13px;
    font-weight: 750;
}

.nx-student-name {
    font-size: 12px;
    font-weight: 700;
    color: #263b50;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.nx-student-sub {
    margin-top: 4px;
    color: #98a3b0;
    font-size: 10px;
}

.nx-interview-column {
    min-width: 0;
}

.nx-column-label {
    font-size: 9px;
    letter-spacing: 0.9px;
    font-weight: 750;
    color: #a1abb7;
    margin-bottom: 5px;
}

.nx-column-value {
    font-size: 11px;
    font-weight: 600;
    color: #43566a;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}


/* =========================================================
   STATUS
   ========================================================= */

.nx-status-badge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 25px;
    padding: 4px 9px;
    border-radius: 20px;
    font-size: 9px;
    font-weight: 750;
    white-space: nowrap;
}

.nx-status-badge.status-scheduled {
    background: #fff1ed;
    color: #e75e4f;
}

.nx-status-badge.status-completed {
    background: #eaf7ef;
    color: #278b5b;
}

.nx-status-badge.status-pending {
    background: #fff7df;
    color: #a57918;
}

.nx-status-badge.status-cancelled {
    background: #fcebed;
    color: #c14d5c;
}

.nx-status-badge.status-rejected {
    background: #fcebed;
    color: #c14d5c;
}

.nx-status-badge.status-default {
    background: #f0f3f6;
    color: #718094;
}


/* =========================================================
   ACTION
   ========================================================= */

.nx-action-column {
    display: flex;
    align-items: center;
    justify-content: flex-end;
}

.nx-edit-btn {
    width: 34px;
    height: 34px;
    border: 1px solid #e0e5eb;
    border-radius: 8px;
    background: #ffffff;
    color: #617286;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: all 0.18s ease;
}

.nx-edit-btn:hover {
    background: #17334b;
    border-color: #17334b;
    color: #ffffff;
}


/* =========================================================
   PAGINATION
   ========================================================= */

.nx-pagination {
    padding: 17px 25px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 15px;
    border-top: 1px solid #edf0f4;
}

.nx-pagination-info {
    color: #8b97a6;
    font-size: 11px;
}

.nx-pagination-controls {
    display: flex;
    align-items: center;
    gap: 12px;
}

.nx-page-btn {
    height: 34px;
    padding: 0 12px;
    border: 1px solid #dfe4ea;
    background: #ffffff;
    color: #53667a;
    border-radius: 8px;
    font-size: 11px;
    font-weight: 650;
    cursor: pointer;
}

.nx-page-btn:hover:not(:disabled) {
    border-color: #17334b;
    color: #17334b;
}

.nx-page-btn:disabled {
    opacity: 0.4;
    cursor: not-allowed;
}

.nx-page-number {
    font-size: 11px;
    font-weight: 700;
    color: #52667a;
}


/* =========================================================
   MODAL BACKDROP
   ========================================================= */

.nx-modal-backdrop {
    position: fixed;
    z-index: 9999;
    left: 0;
    top: 0;
    right: 0;
    bottom: 0;
    background: rgba(16, 34, 50, 0.62);
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 25px;
    box-sizing: border-box;
}


/* =========================================================
   MODAL
   ========================================================= */

.nx-modal {
    width: 100%;
    max-width: 535px;
    max-height: calc(100vh - 50px);
    overflow-y: auto;
    background: #ffffff;
    border-radius: 17px;
    box-shadow: 0 25px 70px rgba(10, 27, 42, 0.28);
    animation: nxModalIn 0.18s ease-out;
}

@keyframes nxModalIn {
    from {
        opacity: 0;
        transform: translateY(10px) scale(0.985);
    }

    to {
        opacity: 1;
        transform: translateY(0) scale(1);
    }
}


/* =========================================================
   MODAL HEADER
   ========================================================= */

.nx-modal-header {
    padding: 21px 23px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    border-bottom: 1px solid #edf0f4;
}

.nx-modal-eyebrow {
    font-size: 9px;
    letter-spacing: 1.4px;
    color: #ff6b5b;
    font-weight: 750;
    margin-bottom: 5px;
}

.nx-modal-header h2 {
    margin: 0;
    color: #17334b;
    font-size: 20px;
    font-weight: 750;
}

.nx-modal-close {
    width: 34px;
    height: 34px;
    border: 0;
    background: #f4f6f8;
    color: #738195;
    border-radius: 8px;
    cursor: pointer;
}

.nx-modal-close:hover {
    background: #fff0ed;
    color: #ff6b5b;
}


/* =========================================================
   MODAL BODY
   ========================================================= */

.nx-modal-body {
    padding: 22px 23px 10px;
}

.nx-form-group {
    margin-bottom: 17px;
}

.nx-form-group label {
    display: block;
    margin-bottom: 7px;
    font-size: 11px;
    font-weight: 700;
    color: #40556a;
}

.nx-form-control {
    width: 100%;
    height: 42px;
    box-sizing: border-box;
    border: 1px solid #dce2e8;
    border-radius: 9px;
    background: #ffffff;
    color: #263b50;
    padding: 0 12px;
    outline: none;
    font-size: 12px;
    transition:
        border-color 0.2s ease,
        box-shadow 0.2s ease;
}

.nx-form-control:focus {
    border-color: #ff6b5b;
    box-shadow: 0 0 0 3px rgba(255, 107, 91, 0.08);
}

.nx-form-control[readonly] {
    background: #f7f8fa;
    color: #728094;
}


/* =========================================================
   MODAL NOTE
   ========================================================= */

.nx-modal-note {
    margin-top: 4px;
    margin-bottom: 12px;
    padding: 11px 12px;
    border-radius: 9px;
    background: #f5f8fa;
    color: #738296;
    font-size: 10px;
    line-height: 1.55;
}

.nx-modal-note i {
    color: #5f7890;
    margin-right: 5px;
}


/* =========================================================
   MODAL FOOTER
   ========================================================= */

.nx-modal-footer {
    padding: 16px 23px 20px;
    display: flex;
    justify-content: flex-end;
    gap: 10px;
    border-top: 1px solid #edf0f4;
}

.nx-cancel-btn {
    height: 40px;
    padding: 0 17px;
    border: 1px solid #dce2e8;
    border-radius: 9px;
    background: #ffffff;
    color: #65768a;
    font-size: 12px;
    font-weight: 650;
    cursor: pointer;
}

.nx-cancel-btn:hover {
    background: #f6f7f9;
}

.nx-save-btn {
    height: 40px;
    padding: 0 19px;
    border: 0;
    border-radius: 9px;
    background: #ff6b5b;
    color: #ffffff;
    font-size: 12px;
    font-weight: 700;
    cursor: pointer;
    box-shadow: 0 5px 13px rgba(255, 107, 91, 0.22);
}

.nx-save-btn:hover {
    background: #ef5d4f;
}

.nx-save-btn:disabled,
.nx-cancel-btn:disabled {
    opacity: 0.55;
    cursor: not-allowed;
}


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 1200px) {

    .nexora-main {
        padding: 30px 25px 50px;
    }

    .nx-summary-grid {
        grid-template-columns: repeat(2, 1fr);
    }

    .nx-interview-row {
        grid-template-columns:
            minmax(180px, 1.4fr)
            minmax(120px, 1fr)
            minmax(125px, 1fr)
            minmax(95px, 0.8fr)
            minmax(135px, 1fr)
            minmax(100px, 0.8fr)
            45px;
    }

}


/* =========================================================
   HEADER RESPONSIVE
   ========================================================= */

@media (max-width: 900px) {

    .nx-page-header {
        min-height: 220px;
        padding: 30px;
        align-items: flex-start;
    }

    .nx-header-stat {
        position: absolute;
        right: 30px;
        bottom: 30px;

        width: 145px;
        min-width: 145px;
        height: 90px;

        margin-left: 0;
    }


    .nx-interview-row {
        grid-template-columns:
            minmax(180px, 1.4fr)
            minmax(130px, 1fr)
            minmax(120px, 1fr)
            45px;
    }

    .nx-interview-row
    .nx-interview-column:nth-child(4),
    .nx-interview-row
    .nx-interview-column:nth-child(5) {
        display: none;
    }

}


@media (max-width: 700px) {

    .nexora-main {
        padding: 22px 14px 40px;
    }


    /* HEADER */

    .nx-page-header {
        min-height: auto;
        padding: 27px 24px;

        display: flex;
        flex-direction: column;
        align-items: stretch;

        gap: 22px;
    }

    .nx-header-content {
        align-items: flex-start;
        flex-direction: column;
    }

    .nx-header-text {
        max-width: 100%;
    }

    .nx-page-header h1 {
        font-size: 29px;
    }

    .nx-header-description {
        max-width: 100%;
        font-size: 12px;
    }

    .nx-header-stat {
        position: relative;
        right: auto;
        bottom: auto;

        width: 100%;
        min-width: 0;
        height: 76px;

        margin: 0;
    }

    .nx-header-stat strong {
        font-size: 27px;
    }


    .nx-summary-grid {
        grid-template-columns: 1fr;
    }

    .nx-filter-bar {
        flex-direction: column;
        align-items: stretch;
    }

    .nx-search-box {
        min-width: 0;
    }

    .nx-filter-select,
    .nx-clear-btn {
        width: 100%;
    }

    .nx-interview-header {
        align-items: flex-start;
        gap: 12px;
        flex-direction: column;
    }

    .nx-interview-row {
        display: block;
        padding: 18px;
        position: relative;
    }

    .nx-student-column {
        margin-bottom: 15px;
        padding-right: 45px;
    }

    .nx-interview-column {
        margin-top: 11px;
    }

    .nx-action-column {
        position: absolute;
        top: 18px;
        right: 18px;
    }

    .nx-pagination {
        align-items: flex-start;
        flex-direction: column;
    }

    .nx-pagination-controls {
        width: 100%;
        justify-content: space-between;
    }

    .nx-modal-backdrop {
        padding: 12px;
    }

}


@media (max-width: 560px) {

    .nx-page-header {
        padding: 24px 20px;
        border-radius: 18px;
    }

    .nx-page-header h1 {
        font-size: 26px;
        letter-spacing: -0.5px;
    }

    .nx-eyebrow {
        font-size: 10px;
        letter-spacing: 1.5px;
    }

    .nx-header-description {
        font-size: 11px;
        line-height: 1.6;
    }

    .nx-header-stat {
        height: 70px;
        border-radius: 13px;
    }

}

sp_widget.script:
(function() {

    /* =========================================================
       NEXORA INTERVIEW MANAGEMENT
       COMPLETE SERVER SCRIPT
       Existing UI / HTML architecture unchanged
       ========================================================= */

    var CFG = {

        interviewTable:
            'x_snc_college_pl_0_interview',

        applicationTable:
            'x_snc_college_pl_0_application',

        studentTable:
            'x_snc_college_pl_0_student',

        applicationField:
            'application',

        interviewerField:
            'interviewer',

        driveField:
            'drive',

        roundField:
            'round_name',

        dateField:
            'interview_date',

        statusField:
            'status',

        studentField:
            'student',

        studentBranchField:
            'branch',

        pageSize:
            8
    };


    /* =========================================================
       INITIAL DATA
       ========================================================= */

    data.pageSize = CFG.pageSize;

    data.page =
        parseInt(
            input && input.page,
            10
        ) || 1;

    if (data.page < 1) {
        data.page = 1;
    }


    data.search =
        input &&
        input.search !== undefined &&
        input.search !== null
            ? (input.search + '')
            : '';


    data.statusFilter =
        input &&
        input.statusFilter !== undefined &&
        input.statusFilter !== null
            ? (input.statusFilter + '')
            : '';


    data.interviews = [];

    data.totalRecords = 0;

    data.pageCount = 1;

    data.hasNext = false;

    data.hasPrevious = false;

    data.needsScheduling = 0;

    data.scheduled = 0;

    data.completedCount = 0;

    data.canEdit = false;

    data.statusOptions = [];

    data.roundOptions = [];

    data.interviewerOptions = [];


    /* =========================================================
       HELPER FUNCTIONS
       ========================================================= */

    function hasField(gr, fieldName) {

        try {

            return gr.isValidField(fieldName);

        } catch (e) {

            return false;
        }
    }


    function getValue(gr, fieldName) {

        try {

            if (!hasField(gr, fieldName)) {
                return '';
            }

            return gr.getValue(fieldName) || '';

        } catch (e) {

            return '';
        }
    }


    function getDisplay(gr, fieldName) {

        try {

            if (!hasField(gr, fieldName)) {
                return '';
            }

            return gr.getDisplayValue(fieldName) || '';

        } catch (e) {

            return '';
        }
    }


    function firstValidField(gr, fields) {

        for (
            var i = 0;
            i < fields.length;
            i++
        ) {

            if (hasField(gr, fields[i])) {
                return fields[i];
            }
        }

        return '';
    }


    function getInitial(name) {

        name =
            (name || '')
                .toString()
                .trim();

        if (!name) {
            return 'S';
        }

        return name
            .substring(0, 1)
            .toUpperCase();
    }


    function normalize(value) {

        return (
            (value || '')
                .toString()
                .toLowerCase()
                .replace(/[\s_-]/g, '')
                .trim()
        );
    }


    function normalizeStatus(value) {

        return normalize(value);
    }


    function resolveStatusValue(statusInput) {

        statusInput =
            (statusInput || '')
                .toString()
                .trim();

        if (!statusInput) {
            return '';
        }


        var normalizedInput =
            normalizeStatus(statusInput);


        /* -----------------------------------------------------
           EXACT VALUE
           ----------------------------------------------------- */

        var choice =
            new GlideRecord('sys_choice');

        choice.addQuery(
            'name',
            CFG.interviewTable
        );

        choice.addQuery(
            'element',
            CFG.statusField
        );

        choice.addQuery(
            'inactive',
            false
        );

        choice.addQuery(
            'value',
            statusInput
        );

        choice.query();

        if (choice.next()) {

            return choice.getValue(
                'value'
            );
        }


        /* -----------------------------------------------------
           EXACT LABEL
           ----------------------------------------------------- */

        choice =
            new GlideRecord('sys_choice');

        choice.addQuery(
            'name',
            CFG.interviewTable
        );

        choice.addQuery(
            'element',
            CFG.statusField
        );

        choice.addQuery(
            'inactive',
            false
        );

        choice.addQuery(
            'label',
            statusInput
        );

        choice.query();

        if (choice.next()) {

            return choice.getValue(
                'value'
            );
        }


        /* -----------------------------------------------------
           NORMALIZED VALUE / LABEL
           ----------------------------------------------------- */

        choice =
            new GlideRecord('sys_choice');

        choice.addQuery(
            'name',
            CFG.interviewTable
        );

        choice.addQuery(
            'element',
            CFG.statusField
        );

        choice.addQuery(
            'inactive',
            false
        );

        choice.query();


        while (choice.next()) {

            var dbValue =
                normalizeStatus(
                    choice.getValue('value')
                );

            var dbLabel =
                normalizeStatus(
                    choice.getValue('label')
                );


            if (
                dbValue === normalizedInput ||
                dbLabel === normalizedInput
            ) {

                return choice.getValue(
                    'value'
                );
            }
        }


        return '';
    }


    function normalizeDateTime(value) {

        if (!value) {
            return '';
        }

        value =
            (value + '')
                .trim()
                .replace('T', ' ');


        if (value.length === 16) {

            value += ':00';
        }

        return value;
    }


    function getStatusClass(status) {

        var s =
            (status || '')
                .toString()
                .toLowerCase();


        if (
            s.indexOf('completed') >= 0 ||
            s.indexOf('complete') >= 0
        ) {

            return 'completed';
        }


        if (
            s.indexOf('scheduled') >= 0
        ) {

            return 'scheduled';
        }


        if (
            s.indexOf('pending') >= 0
        ) {

            return 'pending';
        }


        if (
            s.indexOf('cancel') >= 0
        ) {

            return 'cancelled';
        }


        if (
            s.indexOf('reject') >= 0
        ) {

            return 'rejected';
        }


        if (
            s.indexOf('not set') >= 0 ||
            s.indexOf('notset') >= 0
        ) {

            return 'pending';
        }


        return 'default';
    }


    function isCompletedStatus(
        statusValue,
        statusDisplay
    ) {

        var text =
            (
                (statusValue || '') +
                ' ' +
                (statusDisplay || '')
            )
            .toLowerCase();


        return (
            text.indexOf('completed') >= 0 ||
            text.indexOf('complete') >= 0
        );
    }


    function isScheduledStatus(
        statusValue,
        statusDisplay
    ) {

        var text =
            (
                (statusValue || '') +
                ' ' +
                (statusDisplay || '')
            )
            .toLowerCase();


        return (
            text.indexOf('scheduled') >= 0
        );
    }


    function isNeedsScheduling(
        interviewGR
    ) {

        var interviewer =
            getValue(
                interviewGR,
                CFG.interviewerField
            );


        var interviewDate =
            getValue(
                interviewGR,
                CFG.dateField
            );


        var statusValue =
            getValue(
                interviewGR,
                CFG.statusField
            );


        var statusDisplay =
            getDisplay(
                interviewGR,
                CFG.statusField
            );


        var statusText =
            (
                (statusValue || '') +
                ' ' +
                (statusDisplay || '')
            )
            .toLowerCase();


        return (

            !interviewer ||

            !interviewDate ||

            !statusText ||

            statusText.indexOf('notset') >= 0 ||

            statusText.indexOf('not set') >= 0
        );
    }


    /* =========================================================
       CURRENT USER / ROLE
       ========================================================= */

    var currentUserId =
        gs.getUserID();


    var isAdmin =
        gs.hasRole(
            'x_snc_college_pl_0.placement_admin'
        ) ||
        gs.hasRole(
            'placement_admin'
        );


    var isOfficer =
        gs.hasRole(
            'x_snc_college_pl_0.placement_officer'
        ) ||
        gs.hasRole(
            'placement_officer'
        );


    var isInterviewer =
        gs.hasRole(
            'x_snc_college_pl_0.interviewer'
        ) ||
        gs.hasRole(
            'interviewer'
        );


    var isStudent =
        gs.hasRole(
            'x_snc_college_pl_0.student_user'
        ) ||
        gs.hasRole(
            'student_user'
        );


    /*
     * ADMIN HAS HIGHEST PRIORITY
     */

    if (isAdmin) {

        isOfficer = false;

        isInterviewer = false;

        isStudent = false;
    }


    data.userRole = '';


    if (isAdmin) {

        data.userRole = 'admin';

    } else if (isOfficer) {

        data.userRole = 'officer';

    } else if (isInterviewer) {

        data.userRole = 'interviewer';

    } else if (isStudent) {

        data.userRole = 'student';
    }


    data.canEdit =
        isAdmin ||
        isInterviewer;


    /* =========================================================
       SAVE INTERVIEW
       ========================================================= */

    if (
        input &&
        input.action === 'saveSchedule'
    ) {

        if (!data.canEdit) {

            data.saveResult = false;

            data.saveMessage =
                'You do not have permission to edit interviews.';

        } else {

            var interviewId =
                (input.interviewId || '')
                    .toString();


            if (!interviewId) {

                data.saveResult = false;

                data.saveMessage =
                    'Interview record was not provided.';

            } else {

                var interviewGR =
                    new GlideRecord(
                        CFG.interviewTable
                    );


                if (!interviewGR.get(interviewId)) {

                    data.saveResult = false;

                    data.saveMessage =
                        'Interview record could not be found.';

                } else {


                    /* -----------------------------------------
                       INTERVIEWER CAN EDIT ONLY ASSIGNED RECORD
                       ----------------------------------------- */

                    if (
                        isInterviewer &&
                        !isAdmin
                    ) {

                        var assignedInterviewer =
                            getValue(
                                interviewGR,
                                CFG.interviewerField
                            );


                        if (
                            assignedInterviewer !==
                            currentUserId
                        ) {

                            data.saveResult = false;

                            data.saveMessage =
                                'You can edit only interviews assigned to you.';

                            return;
                        }
                    }


                    var newInterviewer =
                        (
                            input.interviewer ||
                            ''
                        ).toString();


                    var newRound =
                        (
                            input.round_name ||
                            ''
                        ).toString();


                    var newDate =
                        normalizeDateTime(
                            input.interview_date ||
                            ''
                        );


                    var newStatus =
                        (
                            input.status ||
                            ''
                        ).toString();


                    /* -----------------------------------------
                       VALIDATE INTERVIEWER ROLE
                       ----------------------------------------- */

                    if (
                        newInterviewer &&
                        hasField(
                            interviewGR,
                            CFG.interviewerField
                        )
                    ) {

                        var roleGR =
                            new GlideRecord(
                                'sys_user_has_role'
                            );


                        roleGR.addQuery(
                            'user',
                            newInterviewer
                        );


                        roleGR.addQuery(
                            'role.name',
                            'x_snc_college_pl_0.interviewer'
                        );


                        roleGR.query();


                        var hasInterviewerRole =
                            roleGR.hasNext();


                        /*
                         * FALLBACK ROLE
                         */

                        if (!hasInterviewerRole) {

                            roleGR =
                                new GlideRecord(
                                    'sys_user_has_role'
                                );


                            roleGR.addQuery(
                                'user',
                                newInterviewer
                            );


                            roleGR.addQuery(
                                'role.name',
                                'interviewer'
                            );


                            roleGR.query();


                            hasInterviewerRole =
                                roleGR.hasNext();
                        }


                        if (!hasInterviewerRole) {

                            data.saveResult = false;

                            data.saveMessage =
                                'Selected user is not an interviewer.';

                            return;
                        }
                    }


                    /* -----------------------------------------
                       UPDATE FIELDS
                       ----------------------------------------- */

                    if (
                        hasField(
                            interviewGR,
                            CFG.interviewerField
                        )
                    ) {

                        interviewGR.setValue(
                            CFG.interviewerField,
                            newInterviewer
                        );
                    }


                    if (
                        hasField(
                            interviewGR,
                            CFG.roundField
                        )
                    ) {

                        interviewGR.setValue(
                            CFG.roundField,
                            newRound
                        );
                    }


                    if (
                        hasField(
                            interviewGR,
                            CFG.dateField
                        )
                    ) {

                        if (newDate) {

                            interviewGR.setValue(
                                CFG.dateField,
                                newDate
                            );

                        } else {

                            interviewGR.setValue(
                                CFG.dateField,
                                ''
                            );
                        }
                    }


                    if (
                        hasField(
                            interviewGR,
                            CFG.statusField
                        )
                    ) {

                        if (newStatus) {

                            var resolvedStatus =
                                resolveStatusValue(
                                    newStatus
                                );


                            if (resolvedStatus) {

                                interviewGR.setValue(
                                    CFG.statusField,
                                    resolvedStatus
                                );
                            }
                        }
                    }


                    var updatedId =
                        interviewGR.update();


                    if (!updatedId) {

                        data.saveResult = false;

                        data.saveMessage =
                            'Interview could not be updated.';

                        return;
                    }


                    data.saveResult = true;

                    data.saveMessage =
                        'Interview updated successfully.';

                    data.updatedInterviewId =
                        updatedId;
                }
            }
        }
    }


    /* =========================================================
       CLEAN STATUS FILTER
       ========================================================= */

    var rawStatusFilter =
        (data.statusFilter || '')
            .toString()
            .trim();


    if (
        rawStatusFilter === 'all' ||
        rawStatusFilter === 'All' ||
        rawStatusFilter === 'ALL' ||
        rawStatusFilter === '*' ||
        rawStatusFilter === 'undefined' ||
        rawStatusFilter === 'null'
    ) {

        rawStatusFilter = '';
    }


    var resolvedStatusFilter = '';


    if (rawStatusFilter) {

        resolvedStatusFilter =
            resolveStatusValue(
                rawStatusFilter
            );
    }


    /* =========================================================
       BUILD MAIN QUERY
       ========================================================= */

    var gr =
        new GlideRecord(
            CFG.interviewTable
        );


    /*
     * IMPORTANT:
     *
     * ADMIN
     * -> ALL INTERVIEW RECORDS
     *
     * OFFICER
     * -> STUDENTS FROM OFFICER DEPARTMENT/BRANCH
     *
     * INTERVIEWER
     * -> ASSIGNED INTERVIEWS ONLY
     *
     * STUDENT
     * -> OWN INTERVIEWS ONLY
     */


    if (isAdmin) {

        /*
         * NO QUERY RESTRICTION
         *
         * This is intentional.
         * Admin must see every existing Interview record.
         */

    } else if (isInterviewer) {

        /*
         * Interviewer sees only records
         * explicitly assigned to them.
         */

        gr.addQuery(
            CFG.interviewerField,
            currentUserId
        );


    } else if (isStudent) {

        /*
         * Student -> own application interviews
         */

        gr.addQuery(
            CFG.applicationField +
            '.' +
            CFG.studentField +
            '.user',
            currentUserId
        );


    } else if (isOfficer) {

        /* -----------------------------------------------
           PLACEMENT OFFICER BRANCH FILTER
           ----------------------------------------------- */

        var officerGR =
            new GlideRecord(
                'sys_user'
            );


        var officerDepartment =
            '';


        if (
            officerGR.get(
                currentUserId
            )
        ) {

            officerDepartment =
                getDisplay(
                    officerGR,
                    'department'
                );
        }


        var matchingStudentIds = [];


        if (officerDepartment) {

            var officerStudentGR =
                new GlideRecord(
                    CFG.studentTable
                );


            officerStudentGR.query();


            while (
                officerStudentGR.next()
            ) {

                var branch =
                    getDisplay(
                        officerStudentGR,
                        CFG.studentBranchField
                    );


                if (
                    branch &&
                    branch.toLowerCase() ===
                    officerDepartment.toLowerCase()
                ) {

                    matchingStudentIds.push(
                        officerStudentGR.getUniqueValue()
                    );
                }
            }
        }


        if (
            matchingStudentIds.length === 0
        ) {

            /*
             * Return zero records safely.
             */

            gr.addQuery(
                'sys_id',
                '00000000000000000000000000000000'
            );

        } else {

            gr.addQuery(
                CFG.applicationField +
                '.' +
                CFG.studentField,

                'IN',

                matchingStudentIds.join(',')
            );
        }
    }


    /* =========================================================
       STATUS FILTER
       ========================================================= */

    /*
     * IMPORTANT:
     *
     * Status is NOT automatically filtered.
     *
     * Empty statusFilter = ALL STATUSES.
     */

    if (
        rawStatusFilter &&
        resolvedStatusFilter
    ) {

        gr.addQuery(
            CFG.statusField,
            resolvedStatusFilter
        );
    }


    /* =========================================================
       SEARCH
       ========================================================= */

    var searchText =
        (data.search || '')
            .toString()
            .trim();


    if (searchText) {

        var searchParts = [];


        /*
         * Student name
         */

        searchParts.push(
            CFG.applicationField +
            '.' +
            CFG.studentField +
            '.student_nameLIKE' +
            searchText
        );


        /*
         * Fallback for tables where name exists
         */

        searchParts.push(
            CFG.applicationField +
            '.' +
            CFG.studentField +
            '.nameLIKE' +
            searchText
        );


        /*
         * Interviewer
         */

        searchParts.push(
            CFG.interviewerField +
            '.nameLIKE' +
            searchText
        );


        /*
         * Drive
         */

        searchParts.push(
            CFG.driveField +
            '.nameLIKE' +
            searchText
        );


        /*
         * Round
         */

        searchParts.push(
            CFG.roundField +
            'LIKE' +
            searchText
        );


        gr.addEncodedQuery(
            searchParts.join('^OR')
        );
    }


    /* =========================================================
       FINAL QUERY
       ========================================================= */

    var finalEncodedQuery =
        gr.getEncodedQuery();


    /* =========================================================
       TOTAL COUNT
       ========================================================= */

    var countGR =
        new GlideRecord(
            CFG.interviewTable
        );


    countGR.addEncodedQuery(
        finalEncodedQuery
    );


    countGR.query();


    data.totalRecords =
        countGR.getRowCount();


    /* =========================================================
       PAGINATION
       ========================================================= */

    data.pageCount =
        Math.ceil(
            data.totalRecords /
            CFG.pageSize
        );


    if (
        data.pageCount < 1
    ) {

        data.pageCount = 1;
    }


    if (
        data.page >
        data.pageCount
    ) {

        data.page =
            data.pageCount;
    }


    data.hasPrevious =
        data.page > 1;


    data.hasNext =
        data.page <
        data.pageCount;


    var start =
        (data.page - 1) *
        CFG.pageSize;


    var end =
        start +
        CFG.pageSize;


    /* =========================================================
       FETCH CURRENT PAGE
       ========================================================= */

    gr =
        new GlideRecord(
            CFG.interviewTable
        );


    gr.addEncodedQuery(
        finalEncodedQuery
    );


    /*
     * Sort scheduled/newest records first.
     */

    if (
        hasField(
            gr,
            CFG.dateField
        )
    ) {

        gr.orderByDesc(
            CFG.dateField
        );
    }


    gr.orderByDesc(
        'sys_created_on'
    );


    gr.chooseWindow(
        start,
        end
    );


    gr.query();


    while (
        gr.next()
    ) {

        /* -----------------------------------------------
           APPLICATION
           ----------------------------------------------- */

        var applicationId =
            getValue(
                gr,
                CFG.applicationField
            );


        var applicationName =
            getDisplay(
                gr,
                CFG.applicationField
            );


        var studentName =
            '';


        var studentId =
            '';


        var studentBranch =
            '';


        /* -----------------------------------------------
           STUDENT
           ----------------------------------------------- */

        if (applicationId) {

            var applicationGR =
                new GlideRecord(
                    CFG.applicationTable
                );


            if (
                applicationGR.get(
                    applicationId
                )
            ) {

                var studentSysId =
                    getValue(
                        applicationGR,
                        CFG.studentField
                    );


                if (studentSysId) {

                    var studentGR =
                        new GlideRecord(
                            CFG.studentTable
                        );


                    if (
                        studentGR.get(
                            studentSysId
                        )
                    ) {

                        /*
                         * Correct student name field
                         */

                        if (
                            hasField(
                                studentGR,
                                'student_name'
                            )
                        ) {

                            studentName =
                                getDisplay(
                                    studentGR,
                                    'student_name'
                                );
                        }


                        /*
                         * Fallback name
                         */

                        if (!studentName) {

                            if (
                                hasField(
                                    studentGR,
                                    'name'
                                )
                            ) {

                                studentName =
                                    getDisplay(
                                        studentGR,
                                        'name'
                                    );
                            }
                        }


                        /*
                         * Register number
                         */

                        var studentIdField =
                            firstValidField(
                                studentGR,
                                [
                                    'register_number',
                                    'student_id',
                                    'roll_number',
                                    'u_register_number'
                                ]
                            );


                        if (studentIdField) {

                            studentId =
                                getDisplay(
                                    studentGR,
                                    studentIdField
                                );
                        }


                        /*
                         * Branch
                         */

                        studentBranch =
                            getDisplay(
                                studentGR,
                                CFG.studentBranchField
                            );
                    }
                }
            }
        }


        if (!studentName) {

            studentName =
                applicationName ||
                'Student';
        }


        /* -----------------------------------------------
           DRIVE
           ----------------------------------------------- */

        var driveName =
            getDisplay(
                gr,
                CFG.driveField
            );


        if (!driveName) {

            driveName =
                'Not Linked';
        }


        /* -----------------------------------------------
           INTERVIEWER
           ----------------------------------------------- */

        var interviewerId =
            getValue(
                gr,
                CFG.interviewerField
            );


        var interviewerName =
            getDisplay(
                gr,
                CFG.interviewerField
            );


        if (!interviewerName) {

            interviewerName =
                'Not Assigned';
        }


        /* -----------------------------------------------
           ROUND
           ----------------------------------------------- */

        var round =
            getDisplay(
                gr,
                CFG.roundField
            );


        if (!round) {

            round =
                'Not Set';
        }


        /* -----------------------------------------------
           DATE
           ----------------------------------------------- */

        var interviewDate =
            getValue(
                gr,
                CFG.dateField
            );


        var interviewDateDisplay =
            getDisplay(
                gr,
                CFG.dateField
            );


        if (!interviewDateDisplay) {

            interviewDateDisplay =
                'Not Scheduled';
        }


        /* -----------------------------------------------
           STATUS
           ----------------------------------------------- */

        var statusValue =
            getValue(
                gr,
                CFG.statusField
            );


        var statusDisplay =
            getDisplay(
                gr,
                CFG.statusField
            );


        var finalStatus =
            statusDisplay ||
            statusValue ||
            'Not Set';


        /* -----------------------------------------------
           PUSH RECORD
           ----------------------------------------------- */

        data.interviews.push({

            sys_id:
                gr.getUniqueValue(),

            application:
                applicationId,

            studentName:
                studentName,

            studentInitial:
                getInitial(
                    studentName
                ),

            studentId:
                studentId,

            studentBranch:
                studentBranch,

            drive:
                driveName,

            interviewer:
                interviewerName,

            interviewerId:
                interviewerId,

            round:
                round,

            interviewDate:
                interviewDate,

            interviewDateDisplay:
                interviewDateDisplay,

            status:
                finalStatus,

            statusValue:
                statusValue,

            statusClass:
                getStatusClass(
                    finalStatus
                )
        });
    }


    /* =========================================================
       SUMMARY COUNTS
       ========================================================= */

    var summaryGR =
        new GlideRecord(
            CFG.interviewTable
        );


    summaryGR.addEncodedQuery(
        finalEncodedQuery
    );


    summaryGR.query();


    var needsScheduling =
        0;


    var scheduled =
        0;


    var completedCount =
        0;


    while (
        summaryGR.next()
    ) {

        var summaryStatusValue =
            getValue(
                summaryGR,
                CFG.statusField
            );


        var summaryStatusDisplay =
            getDisplay(
                summaryGR,
                CFG.statusField
            );


        if (
            isNeedsScheduling(
                summaryGR
            )
        ) {

            needsScheduling++;
        }


        if (
            isScheduledStatus(
                summaryStatusValue,
                summaryStatusDisplay
            )
        ) {

            scheduled++;
        }


        if (
            isCompletedStatus(
                summaryStatusValue,
                summaryStatusDisplay
            )
        ) {

            completedCount++;
        }
    }


    data.needsScheduling =
        needsScheduling;


    data.scheduled =
        scheduled;


    data.completedCount =
        completedCount;


    /* =========================================================
       COMPATIBILITY VALUES
       ========================================================= */

    data.totalInterviews =
        data.totalRecords;


    data.scheduledCount =
        data.scheduled;


    data.completed =
        data.completedCount;


    data.needsSchedulingCount =
        data.needsScheduling;


    data.pendingCount =
        data.needsScheduling;


    data.upcomingCount =
        data.scheduled;


    data.todayCount =
        0;


    /* =========================================================
       STATUS OPTIONS
       ========================================================= */

    var statusChoiceGR =
        new GlideRecord(
            'sys_choice'
        );


    statusChoiceGR.addQuery(
        'name',
        CFG.interviewTable
    );


    statusChoiceGR.addQuery(
        'element',
        CFG.statusField
    );


    statusChoiceGR.addQuery(
        'inactive',
        false
    );


    statusChoiceGR.orderBy(
        'sequence'
    );


    statusChoiceGR.orderBy(
        'label'
    );


    statusChoiceGR.query();


    while (
        statusChoiceGR.next()
    ) {

        data.statusOptions.push({

            value:
                statusChoiceGR.getValue(
                    'value'
                ),

            label:
                statusChoiceGR.getValue(
                    'label'
                )
        });
    }


    /* =========================================================
       ROUND OPTIONS
       ========================================================= */

    var roundChoiceGR =
        new GlideRecord(
            'sys_choice'
        );


    roundChoiceGR.addQuery(
        'name',
        CFG.interviewTable
    );


    roundChoiceGR.addQuery(
        'element',
        CFG.roundField
    );


    roundChoiceGR.addQuery(
        'inactive',
        false
    );


    roundChoiceGR.orderBy(
        'sequence'
    );


    roundChoiceGR.orderBy(
        'label'
    );


    roundChoiceGR.query();


    while (
        roundChoiceGR.next()
    ) {

        data.roundOptions.push({

            value:
                roundChoiceGR.getValue(
                    'value'
                ),

            label:
                roundChoiceGR.getValue(
                    'label'
                )
        });
    }


    /*
     * Keep fallback only when
     * no choices exist.
     */

    if (
        data.roundOptions.length === 0
    ) {

        data.roundOptions = [

            {
                value: 'round_1',
                label: 'Round 1'
            },

            {
                value: 'round_2',
                label: 'Round 2'
            },

            {
                value: 'round_3',
                label: 'Round 3'
            },

            {
                value: 'hr',
                label: 'HR'
            },

            {
                value: 'final',
                label: 'Final'
            }
        ];
    }


    /* =========================================================
       INTERVIEWER OPTIONS
       ========================================================= */

    var interviewerIds = {};


    /*
     * Custom application role
     */

    var interviewerRoleGR =
        new GlideRecord(
            'sys_user_has_role'
        );


    interviewerRoleGR.addQuery(
        'role.name',
        'x_snc_college_pl_0.interviewer'
    );


    interviewerRoleGR.query();


    while (
        interviewerRoleGR.next()
    ) {

        var uid =
            interviewerRoleGR.getValue(
                'user'
            );


        if (uid) {

            interviewerIds[uid] =
                true;
        }
    }


    /*
     * Fallback generic role
     */

    if (
        Object.keys(
            interviewerIds
        ).length === 0
    ) {

        interviewerRoleGR =
            new GlideRecord(
                'sys_user_has_role'
            );


        interviewerRoleGR.addQuery(
            'role.name',
            'interviewer'
        );


        interviewerRoleGR.query();


        while (
            interviewerRoleGR.next()
        ) {

            var fallbackUid =
                interviewerRoleGR.getValue(
                    'user'
                );


            if (fallbackUid) {

                interviewerIds[
                    fallbackUid
                ] = true;
            }
        }
    }


    var interviewerGR =
        new GlideRecord(
            'sys_user'
        );


    interviewerGR.addQuery(
        'active',
        true
    );


    var idList = [];


    for (
        var interviewerId in interviewerIds
    ) {

        if (
            interviewerIds.hasOwnProperty(
                interviewerId
            )
        ) {

            idList.push(
                interviewerId
            );
        }
    }


    if (
        idList.length > 0
    ) {

        interviewerGR.addQuery(
            'sys_id',
            'IN',
            idList.join(',')
        );


        interviewerGR.orderBy(
            'name'
        );


        interviewerGR.query();


        while (
            interviewerGR.next()
        ) {

            data.interviewerOptions.push({

                value:
                    interviewerGR.getUniqueValue(),

                label:
                    interviewerGR.getDisplayValue(
                        'name'
                    )
            });
        }
    }


    /* =========================================================
       DEBUG
       ========================================================= */

    data.summaryDebug = {

        role:
            data.userRole,

        currentUser:
            currentUserId,

        total:
            data.totalRecords,

        returnedRecords:
            data.interviews.length,

        needsScheduling:
            data.needsScheduling,

        scheduled:
            data.scheduled,

        completed:
            data.completedCount,

        rawStatusFilter:
            rawStatusFilter,

        resolvedStatusFilter:
            resolvedStatusFilter,

        finalQuery:
            finalEncodedQuery
    };


})();
